import{_ as r,C as e,c as o,o as i,aj as h,G as a,w as l}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"What Instruments (Scripts) to Trade","description":"","frontmatter":{"outline":"deep","prev":{"text":"Finding Your Style","link":"/trading-with-pav/finding-your-style"},"next":{"text":"Summary - Trading with PAV","link":"/trading-with-pav/summary-trading-with-pav"}},"headers":[],"relativePath":"trading-with-pav/what-instruments-scripts-to-trade.md","filePath":"trading-with-pav/what-instruments-scripts-to-trade.md"}'),m={name:"trading-with-pav/what-instruments-scripts-to-trade.md"};function c(d,t,u,p,g,f){const n=e("GraphComment"),s=e("ClientOnly");return i(),o("div",null,[t[0]||(t[0]=h('<h1 id="what-instruments-scripts-to-trade" tabindex="-1">What Instruments (Scripts) to Trade <a class="header-anchor" href="#what-instruments-scripts-to-trade" aria-label="Permalink to &quot;What Instruments (Scripts) to Trade&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#what-instruments-scripts-to-trade-1">What Instruments (Scripts) to Trade?</a></li><li><a href="#steps-to-choose-right-trading-instruments">Steps to Choose Right Trading Instruments</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="what-instruments-scripts-to-trade-1" tabindex="-1">What Instruments (Scripts) to Trade? <a class="header-anchor" href="#what-instruments-scripts-to-trade-1" aria-label="Permalink to &quot;What Instruments (Scripts) to Trade?&quot;">​</a></h2><p>Did you know that many professional and institutional traders only focus on one or two scripts or only a few another trading instruments? The reason for that is to enable them to become really proficient with the instrument they chose.</p><p>A good analogy for why this is beneficial can be found by looking at the way lawyers practice law. As a lawyer, you can specialize in many fields, but the best lawyers only focus on one particular area. They have one field on which they concentrate all their time and effort, and this is what allows them to be the best in their chosen area of expertise.</p><p>Professional traders know all the necessary aspects of the market they trade. They know the average volatility, correlation to other instruments, the average impact of different macroeconomic news, as well as average volumes. They know if the market tends to move in spike or if it moves in a more subdued and calm manner. They also develop some sense of feeling for their core market. It’s something that is hard to put into words, but it is there.</p><h2 id="steps-to-choose-right-trading-instruments" tabindex="-1">Steps to Choose Right Trading Instruments <a class="header-anchor" href="#steps-to-choose-right-trading-instruments" aria-label="Permalink to &quot;Steps to Choose Right Trading Instruments&quot;">​</a></h2><ul><li>First decide how much time do you want to dedicate to trading i.e. <strong>Full Time</strong> or <strong>Part Time</strong>. If Part time then select the available segments active in your Part Time.<br> Full Time will have lots of options to choose than Part Time</li><li>Next is whatever segments are chosen select few scripts and test the following: <ul><li><strong>Liquidity</strong>: Open DOM and check whether the bid-ask is tight (narrow also works).</li><li><strong>Volume</strong>: Open 1 min chart and check whether there is enough volume under each candle and is normal volatile.</li></ul></li><li>Start “<strong>The Development Stages</strong>” and in stage 1 Filter out instruments which have least trading opportunities in your Style i.e. Intraday, Swing or Long Term Investment.</li><li>Finalize <strong>max 2 instruments</strong> and continue with the “The Development Stages”.</li></ul><p>That’s all there is for Selecting Scripts. If performance of the 2 instruments is good you can increase instruments if you highly regard that.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',10)),a(s,null,{default:l(()=>[a(n)]),_:1})])}const v=r(m,[["render",c]]);export{y as __pageData,v as default};
